async function openSessionSocket(
  url: string
): Promise<{socket: WebSocket; sessionId: string; connectedKeys: string[]}> {
  const socket = dialSubprotocolSocket(url);
  return new Promise(resolve => {
    const onMessage = (raw: RawData) => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      if (frame.type !== 'connected') return;
      socket.off('message', onMessage);
      resolve({
        socket,
        sessionId: frame.sessionId ?? '',
        connectedKeys: Object.keys(frame).sort(),
      });
    };
    socket.on('message', onMessage);
  });
}

async function reconnectAndCollectReplay(url: string): Promise<WireFrame[]> {
  const socket = dialSubprotocolSocket(url);
  const collected: WireFrame[] = [];
  return new Promise(resolve => {
    const onMessage = (raw: RawData) => {
      const parsed = JSON.parse(String(raw)) as WireFrame;
      collected.push(parsed);
      if (parsed.type === 'connected') {
        socket.send(JSON.stringify({type: 'ping', timestamp: 7}));
        return;
      }
      if (parsed.type !== 'pong') return;
      socket.off('message', onMessage);
      resolve(collected);
    };
    socket.on('message', onMessage);
  });
}

function dialSubprotocolSocket(url: string): WebSocket {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 'token-1']);
  sockets.push(socket);
  return socket;
}

async function sendAndBarrierPing(socket: WebSocket, payload: Record<string, unknown>): Promise<WireFrame[]> {
  const frames: WireFrame[] = [];
  return new Promise(resolve => {
    const onMessage = (raw: RawData) => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      frames.push(frame);
      if (frames.length === 1) {
        socket.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      if (frame.type !== 'pong') return;
      socket.off('message', onMessage);
      resolve(frames);
    };
    socket.on('message', onMessage);
    socket.send(JSON.stringify(payload));
  });
}

function isoTimestamp(stamp: unknown): boolean {
  return typeof stamp === 'string' && Number.isFinite(Date.parse(stamp));
}

